import sys
import re

def main():
    text = sys.stdin.read()
    env = {}

    # One assignment per line: "<name> <- <name or integer>;"
    assign_re = re.compile(
        r'^\s*([A-Za-z_]\w*)\s*<-\s*([A-Za-z_]\w*|[-+]?\d+)\s*;?\s*$'
    )

    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue

        # Drop any trailing comment
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue

        m = assign_re.match(line)
        if not m:
            # Skip prose and any other non-assignment lines
            continue

        target, src = m.group(1), m.group(2)
        if re.fullmatch(r'[-+]?\d+', src):
            val = int(src)
        else:
            val = env.get(src, 0)
        env[target] = val

    order = list("abcdefghijklmnop") + ["TMP"]
    parts = []
    for name in order:
        parts.append(f"{name} ?= {env.get(name, 0)};")
    print(" ".join(parts))

if __name__ == "__main__":
    main()
